//! 💰️ Complete PNG logical bytes and native interpreted entities retain one caller-owned ledger.
use super::PngSnapshot;
use semio_framework_os_kernel::sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,ValueError,ValueRefusalKind,artifact::RowWriter,validate_sqlite_database_schema_controlled};
use semio_framework_value::{NativeDecodeControl,native_decoding::NativeDecodeProgress};
#[path="../⚠️syntax/🦀️.rs"]mod syntax;
#[path="../🗜️compression/🦀️.rs"]mod compression;
#[path="../🌈️scanline/🦀️.rs"]mod scanline;
#[path="../🧩️chunks/🦀️.rs"]mod chunks;
#[path="../🔍️rows/🦀️.rs"]mod rows;
#[path="../🛫️projection/🦀️.rs"]mod projection;
#[path="../🛬️reconstruction/🦀️.rs"]mod reconstruction;
type Result<T>=std::result::Result<T,ValueError>;
const SQL:&str=include_str!("../🗄️.sql");
 const TABLES:[(&str,usize);24]=[("png_background",4),("png_chromaticity",9),("png_chunk",4),("png_deflate_block",9),("png_deflate_code",4),("png_deflate_length",5),("png_deflate_token",7),("png_document",3),("png_gamma",2),("png_idat",3),("png_ihdr",8),("png_inflated_tail",4),("png_literal_octet",4),("png_packed_remainder",3),("png_palette",6),("png_physical",4),("png_sample",4),("png_scanline",9),("png_srgb",2),("png_stream",7),("png_text",7),("png_time",7),("png_transparency",4),("png_unknown_octet",4)];
 fn extent(limits:semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits)->Result<()>{let mut bytes=0usize;for statement in SQL.split(';'){bytes=bytes.checked_add(statement.trim().len()).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"PNG schema bytes overflow"))?;}for(name,_)in TABLES{bytes=bytes.checked_add(name.len()).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"PNG schema names overflow"))?;}if bytes.max(SQL.len())>limits.max_schema_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"PNG authored schema exceeds caller bytes"))}if limits.max_tables<TABLES.len()||TABLES.iter().any(|(_,width)|*width>limits.max_columns)||limits.max_rows<1{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"PNG authored relational extent exceeds caller limits"))}Ok(())}
 struct NativeRows<'c,'p>{control:&'c mut NativeDecodeControl<'p>,limits:semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits,rows:usize,bytes:usize}
 impl NativeRows<'_,'_>{fn row(&mut self,cells:&[semio_framework_os_kernel::sqlite_snapshot::artifact::Cell<'_>])->Result<i64>{use semio_framework_os_kernel::sqlite_snapshot::artifact::Cell;let width=cells.len().checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"PNG semantic column count overflow"))?;if width>self.limits.max_columns{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"PNG semantic columns exceed caller limit"))}let mut bytes=8usize;for cell in cells{bytes=bytes.checked_add(match cell{Cell::Null=>0,Cell::Integer(_)|Cell::Real(_)|Cell::Float32(_)=>8,Cell::Text(text)=>text.len(),Cell::Blob(bytes)=>bytes.len()}).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"PNG semantic cell bytes overflow"))?;}let rows=self.rows.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"PNG semantic row count overflow"))?;let total=self.bytes.checked_add(bytes).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"PNG semantic value bytes overflow"))?;if rows>self.limits.max_rows{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"PNG semantic rows exceed caller limit"))}if total>self.limits.max_value_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"PNG semantic values exceed caller limit"))}for cell in cells{match cell{Cell::Text(text)=>{for piece in text.as_bytes().chunks(256){self.control.advance(piece.len())?;}},Cell::Blob(bytes)=>{for piece in bytes.chunks(256){self.control.advance(piece.len())?;}},_=>self.control.step()?,}}self.control.step()?;self.rows=rows;self.bytes=total;i64::try_from(rows).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"PNG semantic identity exceeds integer64"))}}
 impl projection::Sink for NativeRows<'_,'_>{fn insert_key(&mut self,_table:&str,_key:i64,cells:&[semio_framework_os_kernel::sqlite_snapshot::artifact::Cell<'_>])->Result<()>{self.row(cells).map(|_|())}fn insert(&mut self,_table:&str,cells:&[semio_framework_os_kernel::sqlite_snapshot::artifact::Cell<'_>])->Result<i64>{self.row(cells)}}
 pub(super) fn admit_record(record:&semio_framework_dsl_record::RecordValue,limits:semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits,native:&mut NativeDecodeControl<'_>)->Result<()>{use semio_framework_dsl_record::FieldValue;extent(limits)?;native.scoped_stage(|native|{native.begin_stage(0)?;if record.fields.len()!=2||record.fields.keys().any(|id|*id>=2){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"PNG root has undeclared fields"))}let schema=match record.fields.get(&0){Some(FieldValue::Text(schema))=>schema.as_str(),_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"PNG schema requires authored text"))};let bytes=match record.fields.get(&1){Some(FieldValue::Bytes64(bytes))=>bytes.as_slice(),_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"PNG carrier requires authored bytes"))};let model=match chunks::parse(bytes,native){Ok(model)=>Some(model),Err(syntax::Error::Syntax(_))=>None,Err(syntax::Error::Refusal(error))=>return Err(error)};native.scoped_stage(|native|{native.begin_stage(0)?;let mut writer=NativeRows{control:native,limits,rows:0,bytes:0};projection::write(schema,model.as_ref(),bytes,&mut writer)?;writer.control.checkpoint()})})}
 
fn interpret(snapshot:&PngSnapshot,phase:SqliteSnapshotPhase,control:&mut SqliteSnapshotControl<'_>)->Result<Option<chunks::Native>>{control.allocation_stage(phase,|remaining,checkpoint|{let mut callback=|event:NativeDecodeProgress|checkpoint(event.completed,event.total);let mut native=NativeDecodeControl::new(remaining,&mut callback);let result=match chunks::parse(&snapshot.bytes,&mut native){Ok(value)=>Ok(Some(value)),Err(syntax::Error::Syntax(_))=>Ok(None),Err(syntax::Error::Refusal(error))=>Err(error)};(result,native.owned_bytes())})?}
pub(super) fn project(snapshot:&PngSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase>{extent(control.limits())?;let model=interpret(snapshot,SqliteSnapshotPhase::ProjectSnapshot,control)?;let mut writer=RowWriter::new(SQL,control)?;projection::write(&snapshot.schema,model.as_ref(),&snapshot.bytes,&mut writer)?;writer.finish()}
pub(super) fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<PngSnapshot>{control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema_controlled(database,SQL,SqliteSnapshotPhase::ReconstructSnapshot,control)?;control.allocation_stage(SqliteSnapshotPhase::ReconstructSnapshot,|remaining,checkpoint|{let mut callback=|event:NativeDecodeProgress|checkpoint(event.completed,event.total);let mut native=NativeDecodeControl::new(remaining,&mut callback);let result=reconstruction::reconstruct(database,&mut native).map(|(schema,bytes)|PngSnapshot{schema,bytes});(result,native.owned_bytes())})?}
pub(crate) fn admit(snapshot:&PngSnapshot,phase:SqliteSnapshotPhase,control:&mut SqliteSnapshotControl<'_>)->Result<()>{extent(control.limits())?;let model=interpret(snapshot,phase,control)?;let mut writer=RowWriter::borrowed(control,phase)?;projection::write(&snapshot.schema,model.as_ref(),&snapshot.bytes,&mut writer)?;writer.finish_borrowed()}
pub(crate) fn preflight(snapshot:&PngSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<()>{admit(snapshot,SqliteSnapshotPhase::EncodeNative,control)?;let allowance=snapshot.schema.len().checked_mul(12).and_then(|schema|snapshot.bytes.len().checked_mul(16).and_then(|bytes|schema.checked_add(bytes))).and_then(|bytes|bytes.checked_add(8192)).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"PNG logical Record file ceiling overflow"))?;if allowance>control.limits().max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"PNG logical Record file ceiling exceeds caller limit"))}let total=snapshot.schema.len().checked_add(snapshot.bytes.len()).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"PNG logical borrowed work overflow"))?;control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,total)?;let mut completed=0;for piece in snapshot.schema.as_bytes().chunks(65536){completed+=piece.len();control.checkpoint(SqliteSnapshotPhase::EncodeNative,completed,total)?;}for piece in snapshot.bytes.chunks(65536){completed+=piece.len();control.checkpoint(SqliteSnapshotPhase::EncodeNative,completed,total)?;}control.checkpoint(SqliteSnapshotPhase::EncodeNative,total,total)}
